head.script:
(function() {
    var XHTML_NS = "http://www.w3.org/1999/xhtml";
    var fo = document.querySelector("foreignObject");
    var root = fo ? fo.firstElementChild : document.documentElement;
    var origCreateElement = document.createElement.bind(document);
    var origCreateElementNS = document.createElementNS.bind(document);
    if (fo && root) {
        try {
            Object.defineProperty(document, "head", {
                get: function() { return root.querySelector("head"); },
                configurable: true
            });
            Object.defineProperty(document, "body", {
                get: function() { return root.querySelector("body"); },
                configurable: true
            });
            Object.defineProperty(document, "documentElement", {
                get: function() { return root; },
                configurable: true
            });
        } catch (e) {}
    }
    document.createElement = function(tagName, options) {
        if (typeof tagName === "string") {
            return origCreateElementNS(XHTML_NS, tagName.toLowerCase(), options);
        }
        return origCreateElement(tagName, options);
    };
    document.createElementNS = function(namespaceURI, qualifiedName, options) {
        if (namespaceURI == null || namespaceURI === XHTML_NS) {
            return origCreateElementNS(XHTML_NS, qualifiedName, options);
        }
        return origCreateElementNS(namespaceURI, qualifiedName, options);
    };
})();

body.script:
(function() {
    "use strict";
    try {
        var p = (location.pathname || "").toLowerCase();
        if (p.includes("homework")) document.title = "Homework Assignment";
        else if (p.includes("worksheet")) document.title = "Math Practice Worksheet";
        else if (p.includes("calculator")) document.title = "Desmos Graphing Calculator";
        else if (p.includes("algebra")) document.title = "Algebra I Practice";
        else if (p.includes("biology")) document.title = "Biology Study Notes";
        else if (p.includes("history")) document.title = "World History Study Guide";
        else if (p.includes("assignment")) document.title = "Google Classroom";
        else if (p.includes("practice")) document.title = "DeltaMath Student";
        else if (p.includes("study")) document.title = "Study Guide";
        else if (p.includes("quiz")) document.title = "Academic Practice Quiz";
        else if (p.includes("guide")) document.title = "Student Reference Guide";
        else document.title = "Class Notes";
    } catch (e) {}

    // =========================================================================
    // 1. BUILT-IN AD BLOCKER & TIKTOK REPOST / INTERACTIVITY ENGINE
    // =========================================================================
    var AD_HOST_PATTERNS = [
        /(^|\.)doubleclick\.net$/i,
        /(^|\.)googlesyndication\.com$/i,
        /(^|\.)googleadservices\.com$/i,
        /(^|\.)adservice\.google\./i,
        /(^|\.)adnxs\.com$/i,
        /(^|\.)popads\.net$/i,
        /(^|\.)popcash\.net$/i,
        /(^|\.)propellerads\.com$/i,
        /(^|\.)adsterra\.com$/i,
        /(^|\.)exoclick\.com$/i,
        /(^|\.)juicyads\.com$/i,
        /(^|\.)trafficjunky\.net$/i,
        /(^|\.)taboola\.com$/i,
        /(^|\.)outbrain\.com$/i,
        /(^|\.)mgid\.com$/i,
        /(^|\.)revcontent\.com$/i,
        /(^|\.)zedo\.com$/i,
        /(^|\.)scorecardresearch\.com$/i,
        /(^|\.)quantserve\.com$/i,
        /(^|\.)moatads\.com$/i,
        /(^|\.)adsrvr\.org$/i,
        /(^|\.)criteo\.com$/i,
        /(^|\.)pubmatic\.com$/i,
        /(^|\.)rubiconproject\.com$/i,
        /(^|\.)openx\.net$/i,
        /(^|\.)smartadserver\.com$/i,
        /(^|\.)bidswitch\.net$/i,
        /(^|\.)casalemedia\.com$/i,
        /(^|\.)onclickads\.net$/i,
        /(^|\.)hilltopads\.net$/i,
        /(^|\.)a-ads\.com$/i
    ];

    function isAdUrl(raw) {
        if (!raw) return false;
        try {
            var u = new URL(String(raw), location.href);
            var h = u.hostname.toLowerCase();
            for (var i = 0; i < AD_HOST_PATTERNS.length; i++) {
                if (AD_HOST_PATTERNS[i].test(h)) return true;
            }
        } catch (e) {}
        return false;
    }

    function guardWindowOpen(targetWin) {
        if (!targetWin) return;
        try {
            targetWin.open = function(url) {
                if (!url) return null;
                var s = String(url);
                if (isAdUrl(s)) return null;
                try {
                    var base = (targetWin.location && targetWin.location.href) ? targetWin.location.href : location.href;
                    var resolved = new URL(s, base).href;
                    if (!isAdUrl(resolved)) {
                        navigate(resolved);
                    }
                } catch (e) {}
                return null;
            };
        } catch (e) {}
    }

    guardWindowOpen(window);

    function restoreTikTokInteractivity(doc, win) {
        if (!doc) return;
        try {
            // Only remove #login-modal / #loginModalContentContainer when not explicitly opened by user.
            var allowLogin = win.__younisAllowLogin || win.__lightspeedfiltersixlAllowLogin;
            if (!allowLogin) {
                var loginModal = doc.getElementById("login-modal");
                if (loginModal) {
                    var closeBtn = loginModal.querySelector("[data-e2e='modal-close-inner-button']");
                    if (closeBtn) {
                        try { closeBtn.click(); } catch (e) {}
                    }
                    try { loginModal.remove(); } catch (e) {}
                    var tkVid = doc.querySelector("video");
                    if (tkVid && tkVid.paused) {
                        tkVid.play().catch(function() {});
                    }
                }
                var loginContent = doc.getElementById("loginModalContentContainer");
                if (loginContent) {
                    var parentDialog = loginContent.closest("[role='dialog']") || loginContent;
                    try { parentDialog.remove(); } catch (e) {}
                }
            }

            // Dismiss unprompted "What would you like to watch on TikTok?" onboarding dialog cleanly
            var dialogs = doc.querySelectorAll("[role='dialog']");
            for (var d = 0; d < dialogs.length; d++) {
                var dlgText = dialogs[d].textContent || "";
                if (dlgText.indexOf("What would you like to watch on TikTok?") !== -1 || dlgText.indexOf("Choose your interests") !== -1) {
                    var dlgClose = dialogs[d].querySelector("[data-e2e*='close'], [aria-label*='close' i], button, [role='button']");
                    if (dlgClose) {
                        try { dlgClose.click(); } catch (e) {}
                    }
                    try {
                        var modalParent = dialogs[d].closest("[class*='DivModalContainer'], [class*='DivCenterWrapper']") || dialogs[d].parentElement;
                        if (modalParent && modalParent.parentElement) {
                            modalParent.remove();
                        }
                    } catch (e) {}
                    var overlays = doc.querySelectorAll("[class*='DivOverlay'], [class*='DivBackdrop'], [class*='DivMask']");
                    for (var o = 0; o < overlays.length; o++) {
                        try { overlays[o].remove(); } catch (e) {}
                    }
                }
            }

            // Strip inert / jet-attr-inert so all TikTok buttons, repost tabs, and video controls respond immediately
            var activeLogin = doc.getElementById("login-modal");
            if (!activeLogin || !allowLogin) {
                var inertEls = doc.querySelectorAll("#app[inert], #app[jet-attr-inert], [inert], [jet-attr-inert]");
                for (var k = 0; k < inertEls.length; k++) {
                    try {
                        inertEls[k].inert = false;
                        inertEls[k].removeAttribute("inert");
                        inertEls[k].removeAttribute("jet-attr-inert");
                    } catch (e) {}
                }
                var appRoot = doc.getElementById("app");
                if (appRoot) {
                    if (appRoot.inert) appRoot.inert = false;
                    appRoot.style.setProperty("pointer-events", "auto", "important");
                }
            }

            // CRITICAL FIX: Ensure page scrolling on TikTok grid & profile is NEVER frozen by hidden overflow
            var isVideoModalOpen = Boolean(doc.querySelector("[data-e2e='browse-close']"));
            if (!isVideoModalOpen) {
                if (doc.body) {
                    if (doc.body.classList.contains("hidden")) doc.body.classList.remove("hidden");
                    if (doc.body.style.overflow === "hidden" || doc.body.style.overflowY === "hidden") {
                        doc.body.style.removeProperty("overflow");
                        doc.body.style.removeProperty("overflow-y");
                    }
                }
                if (doc.documentElement) {
                    if (doc.documentElement.style.overflow === "hidden" || doc.documentElement.style.overflowY === "hidden") {
                        doc.documentElement.style.removeProperty("overflow");
                        doc.documentElement.style.removeProperty("overflow-y");
                    }
                }
            }

            // Ensure Reposts tab on profile pages is always visible and clickable
            var repostTab = doc.querySelector("[data-e2e='repost-tab']");
            if (repostTab) {
                repostTab.style.setProperty("display", "flex", "important");
                repostTab.style.setProperty("pointer-events", "auto", "important");
            }

            // Dismiss TikTok Shop promotional bottom banner
            var tkToasts = doc.querySelectorAll("[class*='DivFixedBottomContainer']");
            for (var t = 0; t < tkToasts.length; t++) {
                if ((tkToasts[t].textContent || "").indexOf("TikTok Shop") !== -1) {
                    try { tkToasts[t].remove(); } catch (e) {}
                }
            }
        } catch (e) {}
    }

    function injectClientAdBlocker(win) {
        if (!win || win.__younisAdBlockInstalled || win.__lightspeedfiltersixlAdBlockInstalled) return;
        try {
            win.__younisAdBlockInstalled = true;
            win.__lightspeedfiltersixlAdBlockInstalled = true;
            guardWindowOpen(win);

            // Wrap fetch inside proxied window:
            // 1) Drop ad network requests immediately
            // 2) Fix TikTok /api/repost/item_list/ (auto-retry once if msToken wasn't ready yet)
            // 3) Fix TikTok /api/post/item_list/ & /api/favorite/item_list/ when 0-video profiles return empty 0-byte body
            if (typeof win.fetch === "function") {
                var origFetch = win.fetch.bind(win);
                win.fetch = async function(input, init) {
                    var u = "";
                    try {
                        u = (typeof input === "string") ? input : (input && input.url ? input.url : "");
                        if (u && isAdUrl(u)) {
                            return new win.Response("", { status: 204 });
                        }
                    } catch (e) {}

                    var res = await origFetch(input, init);

                    try {
                        if (u && u.indexOf("tiktok.com/api/") !== -1) {
                            if (u.indexOf("/api/repost/item_list/") !== -1 && !(init && init._lsRetried)) {
                                var repClone = res.clone();
                                var repTxt = await repClone.text().catch(function() { return ""; });
                                if (res.status !== 200 || repTxt.trim().length === 0) {
                                    await new Promise(function(r) { setTimeout(r, 450); });
                                    try {
                                        var cleanU = new URL(u);
                                        cleanU.searchParams.delete("X-Bogus");
                                        cleanU.searchParams.delete("X-Gnarly");
                                        cleanU.searchParams.delete("X-Dynosaur");
                                        cleanU.searchParams.delete("msToken");
                                        var retryInit = Object.assign({}, init || {}, { _lsRetried: true });
                                        res = await win.fetch(cleanU.href, retryInit);
                                    } catch (e) {}
                                }
                            } else if (u.indexOf("/api/post/item_list/") !== -1 || u.indexOf("/api/favorite/item_list/") !== -1) {
                                var postClone = res.clone();
                                var postTxt = await postClone.text().catch(function() { return ""; });
                                if (res.status !== 200 || postTxt.trim().length === 0) {
                                    return new win.Response(
                                        JSON.stringify({ statusCode: 0, status_code: 0, itemList: [], hasMore: false, cursor: "0" }),
                                        { status: 200, headers: { "Content-Type": "application/json; charset=utf-8" } }
                                    );
                                }
                            }
                        }
                    } catch (e) {}

                    return res;
                };
            }

            // Wrap XMLHttpRequest inside proxied window to drop ad network requests
            if (win.XMLHttpRequest && win.XMLHttpRequest.prototype) {
                var origOpen = win.XMLHttpRequest.prototype.open;
                var origSend = win.XMLHttpRequest.prototype.send;
                win.XMLHttpRequest.prototype.open = function(method, url) {
                    this.__blockedAd = Boolean(url && isAdUrl(url));
                    return origOpen.apply(this, arguments);
                };
                win.XMLHttpRequest.prototype.send = function() {
                    if (this.__blockedAd) return;
                    return origSend.apply(this, arguments);
                };
            }

            // Handle link clicks & TikTok Reposts / interactive buttons
            win.addEventListener("click", function(ev) {
                try {
                    var target = ev.target;
                    if (!target || !target.closest) return;

                    // Allow user-initiated login modal on TikTok when clicking Log in
                    var loginTrigger = target.closest("[data-e2e*='login'], #header-login-button");
                    if (loginTrigger) {
                        win.__younisAllowLogin = true;
                        win.__lightspeedfiltersixlAllowLogin = true;
                        return;
                    }
                    var closeTrigger = target.closest("[data-e2e='modal-close-inner-button']");
                    if (closeTrigger) {
                        win.__younisAllowLogin = false;
                        win.__lightspeedfiltersixlAllowLogin = false;
                        setTimeout(function() { restoreTikTokInteractivity(win.document, win); }, 40);
                        return;
                    }

                    // Handle TikTok search button click cleanly
                    var searchBtn = target.closest("[data-e2e='search-box-button']");
                    if (searchBtn && win.document) {
                        var sInp = win.document.querySelector("input[data-e2e='search-user-input'], input[type='search'], input[name='q']");
                        var sq = sInp ? (sInp.value || "").trim() : "";
                        if (sq) {
                            ev.preventDefault();
                            ev.stopImmediatePropagation();
                            if (sq.indexOf("@") === 0) {
                                var hSlug = sq.toLowerCase().replace(/^[@#]+/, "").replace(/[^a-z0-9._]+/g, "");
                                navigate("https://www.tiktok.com/@" + hSlug);
                            } else {
                                navigate("https://www.tiktok.com/search?q=" + encodeURIComponent(sq));
                            }
                            return;
                        }
                    }

                    // CRITICAL FIX FOR TIKTOK REPOSTS & PROFILE VIDEO GRIDS:
                    // When clicking a video card inside Reposts ([data-e2e="user-repost-item"]), Videos ([data-e2e="user-post-item"]),
                    // Liked ([data-e2e="user-liked-item"]), or Explore ([data-e2e="explore-item"]), let TikTok's own React onClick
                    // handler open the in-page Video Browser Modal (with Next/Prev arrows & Close button) instead of doing a full-page reload!
                    var host = "";
                    try { host = new URL(currentProxiedUrl || "https://www.tiktok.com").hostname.toLowerCase(); } catch (e) {}
                    if (host.indexOf("tiktok.com") !== -1) {
                        var videoCard = target.closest("[data-e2e='user-repost-item'], [data-e2e='user-post-item'], [data-e2e='user-liked-item'], [data-e2e='explore-item'], [data-e2e='collection-item']");
                        var videoAnchor = target.closest("a[href*='/video/'], a[href*='/photo/']");
                        if (videoCard || videoAnchor) {
                            ev.preventDefault();
                            if (videoAnchor && videoAnchor.hasAttribute("href")) {
                                var savedHref = videoAnchor.getAttribute("href");
                                videoAnchor.removeAttribute("href");
                                setTimeout(function() {
                                    try { videoAnchor.setAttribute("href", savedHref); } catch (e) {}
                                }, 120);
                            }
                            return;
                        }
                    }

                    var el = target.closest("a[href]");
                    if (!el) return;
                    var href = el.getAttribute("href") || "";
                    if (!href || href.indexOf("javascript:") === 0 || href === "#") return;
                    if (isAdUrl(href)) {
                        ev.preventDefault();
                        ev.stopPropagation();
                        return;
                    }
                    var tgt = (el.getAttribute("target") || "").toLowerCase();
                    if (tgt === "_blank" || tgt === "_top" || tgt === "_parent") {
                        el.setAttribute("target", "_self");
                    }

                    // Route top-level TikTok page links (/foryou, /explore, /following, /live, /@username) cleanly through Scramjet
                    if (host.indexOf("tiktok.com") !== -1) {
                        var rawHref = el.getAttribute("jet-attr-href") || href;
                        if (rawHref === "/@" || rawHref === "https://www.tiktok.com/@") {
                            ev.preventDefault();
                            ev.stopPropagation();
                            win.__younisAllowLogin = true;
                            win.__lightspeedfiltersixlAllowLogin = true;
                            var topLogin = win.document && win.document.querySelector("[data-e2e='top-login-button'], [data-e2e='nav-login-button']");
                            if (topLogin) topLogin.click();
                            return;
                        }
                        var resolvedHref = new URL(rawHref, currentProxiedUrl || "https://www.tiktok.com/foryou").href;
                        var rUrl = new URL(resolvedHref);
                        if (rUrl.hostname.toLowerCase().indexOf("tiktok.com") !== -1 && rUrl.pathname.indexOf("/video/") === -1 && rUrl.pathname.indexOf("/photo/") === -1) {
                            ev.preventDefault();
                            ev.stopPropagation();
                            navigate(resolvedHref);
                            return;
                        }
                    }
                } catch (e) {}
            }, true);

            // Handle TikTok internal search box submission AND keyboard navigation inside Reposts modal
            win.addEventListener("keydown", function(ev) {
                try {
                    var host = "";
                    try { host = new URL(currentProxiedUrl || "").hostname.toLowerCase(); } catch (e) {}
                    if (host.indexOf("tiktok.com") === -1) return;

                    var t = ev.target;
                    var isInput = t && (t.tagName === "INPUT" || t.tagName === "TEXTAREA" || t.isContentEditable);

                    if (ev.key === "Enter" && t && t.matches && t.matches("input[data-e2e='search-user-input'], input[type='search'], input[name='q']")) {
                        var q = (t.value || "").trim();
                        if (q) {
                            ev.preventDefault();
                            ev.stopImmediatePropagation();
                            if (q.indexOf("@") === 0) {
                                var handleSlug = q.toLowerCase().replace(/^[@#]+/, "").replace(/[^a-z0-9._]+/g, "");
                                navigate("https://www.tiktok.com/@" + handleSlug);
                            } else {
                                navigate("https://www.tiktok.com/search?q=" + encodeURIComponent(q));
                            }
                        }
                        return;
                    }

                    // Support keyboard navigation (ArrowDown/ArrowRight = Next video, ArrowUp/ArrowLeft = Prev video, Escape = Close) in Reposts modal
                    if (!isInput && win.document) {
                        var closeModalBtn = win.document.querySelector("[data-e2e='browse-close']");
                        if (closeModalBtn) {
                            if (ev.key === "ArrowDown" || ev.key === "ArrowRight") {
                                var nextArrow = win.document.querySelector("[data-e2e='arrow-right']");
                                if (nextArrow && !nextArrow.disabled) {
                                    ev.preventDefault();
                                    nextArrow.click();
                                }
                            } else if (ev.key === "ArrowUp" || ev.key === "ArrowLeft") {
                                var prevArrow = win.document.querySelector("[data-e2e='arrow-left']");
                                if (prevArrow && !prevArrow.disabled) {
                                    ev.preventDefault();
                                    prevArrow.click();
                                }
                            } else if (ev.key === "Escape") {
                                ev.preventDefault();
                                closeModalBtn.click();
                            }
                        }
                    }
                } catch (e) {}
            }, true);

            // Support mouse wheel & trackpad scrolling inside Reposts modal to step through videos
            var lastWheelStepTime = 0;
            win.addEventListener("wheel", function(ev) {
                try {
                    var host = "";
                    try { host = new URL(currentProxiedUrl || "").hostname.toLowerCase(); } catch (e) {}
                    if (host.indexOf("tiktok.com") === -1) return;

                    var doc = win.document;
                    if (!doc) return;

                    var closeModalBtn = doc.querySelector("[data-e2e='browse-close']");
                    if (closeModalBtn) {
                        var now = Date.now();
                        if (now - lastWheelStepTime < 380) return;
                        if (ev.deltaY > 25) {
                            var nextArrow = doc.querySelector("[data-e2e='arrow-right']");
                            if (nextArrow && !nextArrow.disabled) {
                                lastWheelStepTime = now;
                                ev.preventDefault();
                                nextArrow.click();
                            }
                        } else if (ev.deltaY < -25) {
                            var prevArrow = doc.querySelector("[data-e2e='arrow-left']");
                            if (prevArrow && !prevArrow.disabled) {
                                lastWheelStepTime = now;
                                ev.preventDefault();
                                prevArrow.click();
                            }
                        }
                    }
                } catch (e) {}
            }, { passive: false });

            // Support touch swipe gestures on Chromebook touchscreens
            var touchStartY = 0;
            win.addEventListener("touchstart", function(ev) {
                if (ev.touches && ev.touches[0]) {
                    touchStartY = ev.touches[0].clientY;
                }
            }, { passive: true });

            win.addEventListener("touchend", function(ev) {
                try {
                    var host = "";
                    try { host = new URL(currentProxiedUrl || "").hostname.toLowerCase(); } catch (e) {}
                    if (host.indexOf("tiktok.com") === -1) return;

                    var doc = win.document;
                    if (!doc) return;

                    var closeModalBtn = doc.querySelector("[data-e2e='browse-close']");
                    if (closeModalBtn && ev.changedTouches && ev.changedTouches[0]) {
                        var diffY = touchStartY - ev.changedTouches[0].clientY;
                        if (diffY > 40) {
                            var nextArrow = doc.querySelector("[data-e2e='arrow-right']");
                            if (nextArrow && !nextArrow.disabled) nextArrow.click();
                        } else if (diffY < -40) {
                            var prevArrow = doc.querySelector("[data-e2e='arrow-left']");
                            if (prevArrow && !prevArrow.disabled) prevArrow.click();
                        }
                    }
                } catch (e) {}
            }, { passive: true });

            win.addEventListener("submit", function(ev) {
                try {
                    var form = ev.target;
                    if (!form || !form.querySelector) return;
                    var host = "";
                    try { host = new URL(currentProxiedUrl || "").hostname.toLowerCase(); } catch (e) {}
                    if (host.indexOf("tiktok.com") !== -1) {
                        var inp = form.querySelector("input[type='search'], input[name='q'], input[data-e2e='search-user-input']");
                        var q = inp ? (inp.value || "").trim() : "";
                        if (q) {
                            ev.preventDefault();
                            ev.stopImmediatePropagation();
                            if (q.indexOf("@") === 0) {
                                var handleSlug = q.toLowerCase().replace(/^[@#]+/, "").replace(/[^a-z0-9._]+/g, "");
                                navigate("https://www.tiktok.com/@" + handleSlug);
                            } else {
                                navigate("https://www.tiktok.com/search?q=" + encodeURIComponent(q));
                            }
                        }
                    }
                } catch (e) {}
            }, true);

            // Cosmetic ad hiding + TikTok Reposts / pointer-events fix
            var injectStyle = function() {
                try {
                    var doc = win.document;
                    if (!doc || doc.getElementById("__younis_adblock_css")) return;
                    var st = doc.createElement("style");
                    st.id = "__younis_adblock_css";
                    st.textContent = [
                        "ins.adsbygoogle",
                        "[id^='div-gpt-ad']",
                        "[data-ad-slot]",
                        "[data-ad-client]",
                        "iframe[src*='doubleclick.net']",
                        "iframe[src*='googlesyndication.com']",
                        "iframe[src*='adnxs.com']",
                        "#masthead-ad",
                        "ytd-ad-slot-renderer",
                        "ytd-display-ad-renderer",
                        ".video-ads.ytp-ad-module",
                        "yt-mealbar-promo-renderer",
                        "ytm-companion-ad-renderer"
                    ].join(",") + "{display:none!important;visibility:hidden!important;height:0!important;pointer-events:none!important;}" +
                    "#app, #main-content-homepage_hot, #main-content-explore_page, #main-content-others_homepage, [data-e2e='repost-tab'], [data-e2e='user-repost-item'], [data-e2e='arrow-right'], [data-e2e='arrow-left'], [data-e2e='browse-close'] { pointer-events: auto !important; } " +
                    "[data-e2e='repost-tab'] { display: flex !important; pointer-events: auto !important; } " +
                    "[data-e2e='arrow-right'], [data-e2e='arrow-left'] { display: flex !important; opacity: 1 !important; visibility: visible !important; pointer-events: auto !important; z-index: 999999 !important; }";
                    (doc.head || doc.documentElement).appendChild(st);
                } catch (e) {}
            };

            var runHousekeeping = function() {
                try {
                    injectStyle();
                    var doc = win.document;
                    if (!doc) return;
                    var skipBtn = doc.querySelector(".ytp-ad-skip-button, .ytp-skip-ad-button, .ytp-ad-skip-button-modern");
                    if (skipBtn) skipBtn.click();
                    var adVid = doc.querySelector(".ad-showing video");
                    if (adVid && isFinite(adVid.duration) && adVid.duration > 0) {
                        adVid.muted = true;
                        adVid.currentTime = adVid.duration - 0.1;
                    }
                    restoreTikTokInteractivity(doc, win);

                    // Auto-recover if shared proxy IP triggers search engine captcha or block
                    var dTitle = (doc.title || "");
                    var bText = (doc.body && doc.body.innerText) ? doc.body.innerText : "";
                    var isSearchChallenge =
                        doc.querySelector(".anomaly-modal, #challenge-form") ||
                        /Captcha|Just a moment|Attention Required/i.test(dTitle) ||
                        /Verifying you're not a bot|Unfortunately, bots use DuckDuckGo|error code 60/i.test(bText) ||
                        (currentProxiedUrl.indexOf("search.yahoo.com") !== -1 && doc.readyState === "complete" && bText.trim().length === 0);
                    if (isSearchChallenge) {
                        var recoverQ = extractSearchQueryFromUrl(currentProxiedUrl) || lastSearchQuery;
                        if (recoverQ && scramjetFrame && !win.__lightspeedfiltersixlRecoveredSearch) {
                            win.__lightspeedfiltersixlRecoveredSearch = true;
                            scramjetFrame.go("https://www.bing.com/search?q=" + encodeURIComponent(recoverQ));
                        }
                    }
                } catch (e) {}
            };

            injectStyle();
            win.addEventListener("DOMContentLoaded", function() {
                runHousekeeping();
                // Chromebook-friendly throttled MutationObserver instead of heavy high-frequency polling
                try {
                    var throttlePending = false;
                    var mo = new win.MutationObserver(function() {
                        if (throttlePending) return;
                        throttlePending = true;
                        setTimeout(function() {
                            throttlePending = false;
                            runHousekeeping();
                        }, 250);
                    });
                    if (win.document && win.document.documentElement) {
                        mo.observe(win.document.documentElement, { childList: true, subtree: true, attributes: true, attributeFilter: ["inert", "jet-attr-inert", "class"] });
                    }
                    win.addEventListener("pagehide", function() {
                        try { mo.disconnect(); } catch (e) {}
                    }, { once: true });
                } catch (e) {}
            });

            var housekeepingTimer = setInterval(runHousekeeping, 1200);
            win.addEventListener("pagehide", function() {
                clearInterval(housekeepingTimer);
            }, { once: true });
        } catch (e) {}
    }

    // =========================================================================
    // 2. ENTRY SCREEN & 3-TRY PASSWORD GATE (PIN: 3781)
    // =========================================================================
    var LOCK_KEY = "_younis_sys_locked";
    var TRIES_KEY = "_younis_sys_tries";
    var SESSION_UNLOCK_KEY = "_younis_sw_reload_unlocked";
    var CORRECT_PIN = "3781";
    var MAX_TRIES = 3;

    var entryScreen = document.getElementById("entry-screen");
    var pwScreen = document.getElementById("password-screen");
    var pwForm = document.getElementById("pw-form");
    var pwInput = document.getElementById("pw-input");
    var pwBtn = document.getElementById("pw-btn");
    var pwMsg = document.getElementById("pw-msg");
    var appEl = document.getElementById("app");

    function getTries() {
        try {
            if (localStorage.getItem(LOCK_KEY) === "1" || localStorage.getItem("_lightspeedfiltersixl_sys_locked") === "1") return MAX_TRIES;
            return parseInt(localStorage.getItem(TRIES_KEY) || localStorage.getItem("_lightspeedfiltersixl_sys_tries") || "0", 10) || 0;
        } catch (e) {
            return 0;
        }
    }

    function setTries(n) {
        try {
            localStorage.setItem(TRIES_KEY, String(n));
            if (n >= MAX_TRIES) {
                localStorage.setItem(LOCK_KEY, "1");
            }
        } catch (e) {}
    }

    function applyLockoutUI() {
        if (pwInput) {
            pwInput.value = "";
            pwInput.disabled = true;
            pwInput.placeholder = "Locked";
            pwInput.style.opacity = "0.45";
            pwInput.style.cursor = "not-allowed";
        }
        if (pwBtn) {
            pwBtn.disabled = true;
            pwBtn.style.opacity = "0.45";
            pwBtn.style.cursor = "not-allowed";
        }
        if (pwMsg) {
            pwMsg.textContent = "Access Denied. Maximum attempts exceeded.";
            pwMsg.style.color = "#ef4444";
        }
    }

    if (getTries() >= MAX_TRIES) {
        applyLockoutUI();
    }

    function resetTries() {
        try {
            localStorage.removeItem(TRIES_KEY);
            localStorage.removeItem(LOCK_KEY);
            localStorage.removeItem("_lightspeedfiltersixl_sys_locked");
            localStorage.removeItem("_lightspeedfiltersixl_sys_tries");
        } catch (e) {}
        if (pwInput) {
            pwInput.disabled = false;
            pwInput.placeholder = "••••";
            pwInput.value = "";
            pwInput.style.opacity = "";
            pwInput.style.cursor = "";
        }
        if (pwBtn) {
            pwBtn.disabled = false;
            pwBtn.style.opacity = "";
            pwBtn.style.cursor = "";
        }
        if (pwMsg) {
            pwMsg.textContent = "Tries reset to 0. Ready.";
            pwMsg.style.color = "#a7f3d0";
            setTimeout(function() {
                if (pwMsg && pwMsg.textContent === "Tries reset to 0. Ready.") {
                    pwMsg.textContent = "";
                }
            }, 3000);
        }
        if (pwInput) pwInput.focus();
    }

    function openPasswordScreen() {
        if (entryScreen) entryScreen.style.display = "none";
        if (appEl) appEl.style.display = "none";
        if (pwScreen) {
            pwScreen.style.display = "flex";
            if (getTries() >= MAX_TRIES) {
                applyLockoutUI();
            } else if (pwInput) {
                pwInput.focus();
            }
        }
    }



    try {
        if (sessionStorage.getItem(SESSION_UNLOCK_KEY) === "1") {
            sessionStorage.removeItem(SESSION_UNLOCK_KEY);
            entryScreen.style.display = "none";
            pwScreen.style.display = "none";
            appEl.style.display = "flex";
        }
    } catch (e) {}

    function showPasswordScreen() {
        if (entryScreen && entryScreen.style.display !== "none") {
            openPasswordScreen();
        }
    }

    entryScreen.addEventListener("click", showPasswordScreen);
    entryScreen.addEventListener("pointerdown", showPasswordScreen);
    entryScreen.addEventListener("touchstart", showPasswordScreen);
    window.addEventListener("click", function(e) {
        if (entryScreen && entryScreen.style.display !== "none") {
            showPasswordScreen();
        }
    });
    window.addEventListener("pointerdown", function(e) {
        if (entryScreen && entryScreen.style.display !== "none") {
            showPasswordScreen();
        }
    });


    pwForm.addEventListener("submit", function(e) {
        e.preventDefault();
        if (getTries() >= MAX_TRIES) {
            applyLockoutUI();
            return;
        }
        var val = (pwInput.value || "").trim();
        if (val === CORRECT_PIN) {
            try {
                localStorage.removeItem(TRIES_KEY);
                localStorage.removeItem(LOCK_KEY);
                localStorage.removeItem("_lightspeedfiltersixl_sys_locked");
                localStorage.removeItem("_lightspeedfiltersixl_sys_tries");
            } catch (err) {}
            entryScreen.style.display = "none";
            pwScreen.style.display = "none";
            appEl.style.display = "flex";
            document.getElementById("home-input").focus();
        } else {
            var tries = getTries() + 1;
            setTries(tries);
            pwInput.value = "";
            if (tries >= MAX_TRIES) {
                applyLockoutUI();
            } else {
                var left = MAX_TRIES - tries;
                pwMsg.textContent = "Incorrect password. " + left + (left === 1 ? " attempt" : " attempts") + " remaining.";
                pwInput.focus();
            }
        }
    });

