    // Attachment Handlers
    function handleAttachmentFile(file) {
        if (!file) return;
        var r = new FileReader();
        if (file.type.startsWith("image/")) {
            r.onload = function(e) {
                activeAttachment = {
                    type: "image",
                    data: e.target.result,
                    name: file.name
                };
                if (aiPreviewThumb) {
                    aiPreviewThumb.src = e.target.result;
                    aiPreviewThumb.style.display = "block";
                }
                if (aiPreviewName) aiPreviewName.textContent = file.name;
                if (aiAttachmentPreview) aiAttachmentPreview.style.display = "flex";
            };
            r.readAsDataURL(file);
        } else {
            r.onload = function(e) {
                activeAttachment = {
                    type: "text",
                    data: e.target.result,
                    name: file.name
                };
                if (aiPreviewThumb) aiPreviewThumb.style.display = "none";
                if (aiPreviewName) aiPreviewName.textContent = "📄 " + file.name;
                if (aiAttachmentPreview) aiAttachmentPreview.style.display = "flex";
            };
            r.readAsText(file);
        }
    }

