        if (!isAiOpen && !isSolverOpen) return;

        var items = (e.clipboardData || (e.originalEvent && e.originalEvent.clipboardData) || {}).items;
        if (!items) return;
        for (var i = 0; i < items.length; i++) {
            if (items[i].type.indexOf("image") !== -1) {
                var blob = items[i].getAsFile();
                if (blob) {
