    // Web Search Functionality
    async function performWebSearch(query) {
        var snippets = [];
        try {
            var cleanQ = query.replace(/[^\w\s]/g, " ").trim();
            var wikiUrl = "https://en.wikipedia.org/w/api.php?action=query&list=search&srsearch=" + encodeURIComponent(cleanQ) + "&format=json&origin=*";
            var wr = await fetch(wikiUrl);
            if (wr.ok) {
                var wj = await wr.json();
                var sItems = (wj.query && wj.query.search) || [];
                for (var si = 0; si < Math.min(3, sItems.length); si++) {
                    var it = sItems[si];
                    var cleaned = it.snippet.replace(/<[^>]+>/g, "");
                    snippets.push(it.title + ": " + cleaned);
                }
            }
        } catch (e) {}

        try {
            var ddgUrl = "https://api.duckduckgo.com/?q=" + encodeURIComponent(query) + "&format=json&origin=*";
            var dr = await fetch(ddgUrl);
            if (dr.ok) {
                var dj = await dr.json();
                if (dj.AbstractText) {
                    snippets.push("Summary: " + dj.AbstractText);
                } else if (dj.Answer) {
                    snippets.push("Answer: " + dj.Answer);
                }
            }
        } catch (e) {}

        return snippets;
    }

    // Send AI Message (Chat)
    async function sendAiMessage(prompt) {
        var text = (prompt || "").trim();
        var attach = activeAttachment;
        if (!text && !attach) return;

        var userDiv = document.createElement("div");
        userDiv.className = "ai-msg user";
        if (attach && attach.type === "image") {
            var imgEl = document.createElement("img");
            imgEl.src = attach.data;
            imgEl.style.maxWidth = "200px";
            imgEl.style.maxHeight = "160px";
            imgEl.style.borderRadius = "8px";
            imgEl.style.display = "block";
            imgEl.style.marginBottom = "6px";
            userDiv.appendChild(imgEl);
        }
        var spanEl = document.createElement("span");
        spanEl.textContent = text || (attach ? ("Attached: " + attach.name) : "");
        userDiv.appendChild(spanEl);
        aiMsgs.appendChild(userDiv);
        aiInput.value = "";
        aiMsgs.scrollTop = aiMsgs.scrollHeight;
        clearAttachment();

        var botDiv = document.createElement("div");
        botDiv.className = "ai-msg bot";
        botDiv.textContent = isWebSearchEnabled ? "Searching web & thinking..." : "...";
        aiMsgs.appendChild(botDiv);
        aiMsgs.scrollTop = aiMsgs.scrollHeight;

        var msgsToSend = [];
        if (isWebSearchEnabled && text) {
            var webSnippets = await performWebSearch(text);
            if (webSnippets.length > 0) {
                msgsToSend.push({
                    role: "system",
                    content: "Real-time web search findings for user question:\n" + webSnippets.join("\n") + "\nUse these up-to-date facts to formulate your answer accurately."
                });
            }
        }

        // Build history
        for (var hIdx = 0; hIdx < AI_HISTORY.length; hIdx++) {
            msgsToSend.push(AI_HISTORY[hIdx]);
        }

        // Add current user turn
        if (attach && attach.type === "image") {
            msgsToSend.push({
                role: "user",
                content: [
                    { type: "text", text: text || "Carefully examine this image and provide a thorough, accurate solution or explanation." },
                    { type: "image_url", image_url: { url: attach.data } }
                ]
            });
        } else if (attach && attach.type === "text") {
            msgsToSend.push({
                role: "user",
                content: "[File: " + attach.name + "]\n" + attach.data + "\n\n" + (text || "Please analyze this file.")
            });
        } else {
            msgsToSend.push({ role: "user", content: text });
        }

        var modelsToUse = (attach && attach.type === "image") ? VISION_MODELS : TEXT_MODELS;
        var fullResp = "";

        for (var mIdx = 0; mIdx < modelsToUse.length; mIdx++) {
            var model = modelsToUse[mIdx];
            try {
                var resp = await fetch("https://openrouter.ai/api/v1/chat/completions", {
                    method: "POST",
                    headers: {
                        "Authorization": "Bearer " + AI_KEY,
                        "Content-Type": "application/json",
                        "HTTP-Referer": location.origin || "http://localhost",
                        "X-Title": "younis"
                    },
                    body: JSON.stringify({
                        model: model,
                        messages: msgsToSend,
                        stream: true
                    })
                });

                if (!resp.ok || !resp.body) continue;

                var reader = resp.body.getReader();
                var decoder = new TextDecoder();
                var buf = "";
                botDiv.textContent = "";

                while (true) {
                    var chunk = await reader.read();
                    if (chunk.done) break;
                    buf += decoder.decode(chunk.value, { stream: true });
                    var lines = buf.split(/\r?\n/);
                    buf = lines.pop() || "";
                    for (var lIdx = 0; lIdx < lines.length; lIdx++) {
                        var line = lines[lIdx].trim();
                        if (!line.startsWith("data:")) continue;
                        var dataStr = line.slice(5).trim();
                        if (dataStr === "[DONE]") break;
                        try {
                            var parsed = JSON.parse(dataStr);
                            var delta = parsed.choices && parsed.choices[0] && parsed.choices[0].delta;
                            var content = (delta && delta.content) || (parsed.choices && parsed.choices[0] && parsed.choices[0].message && parsed.choices[0].message.content);
                            if (content) {
                                fullResp += content;
                                botDiv.textContent = fullResp;
                                aiMsgs.scrollTop = aiMsgs.scrollHeight;
                            }
                        } catch (e) {}
                    }
                }
                if (fullResp) {
                    AI_HISTORY.push({ role: "user", content: text || "Attached image/file" });
                    AI_HISTORY.push({ role: "assistant", content: fullResp });
                    return;
                }
            } catch (err) {
                console.warn("AI Chat Model error:", err);
            }
        }
        if (!fullResp) {
            botDiv.textContent = "AI model is busy or rate limited. Please try asking again!";
        }
    }

    if (aiForm) {
        aiForm.addEventListener("submit", function(e) {
