    async function popOutToPip() {
        if (!("documentPictureInPicture" in window)) {
            alert("Always-on-top Document PiP requires Google Chrome 116+ on desktop or Chromebook. For other tabs, use the In-Tab Bookmarklet button!");
            return false;
        }
        if (activePipWindow && !activePipWindow.closed) {
            try { activePipWindow.focus(); } catch(e) {}
            return true;
        }
        try {
            var pip = await window.documentPictureInPicture.requestWindow({
                width: 440,
                height: 560
            });
            activePipWindow = pip;

            // Copy all styles to PiP window
            try {
                var allStyles = "";
                for (var i = 0; i < document.styleSheets.length; i++) {
                    var sheet = document.styleSheets[i];
                    try {
                        for (var j = 0; j < sheet.cssRules.length; j++) {
                            allStyles += sheet.cssRules[j].cssText + "\n";
                        }
                    } catch (e) {
                        if (sheet.href) {
                            var link = pip.document.createElement("link");
                            link.rel = "stylesheet";
                            link.href = sheet.href;
                            pip.document.head.appendChild(link);
                        }
                    }
                }
                var styleEl = pip.document.createElement("style");
                styleEl.textContent = allStyles + "\nhtml,body{background:#050507!important;margin:0!important;padding:0!important;overflow:hidden!important;}";
                pip.document.head.appendChild(styleEl);
            } catch (e) {}

            pip.document.title = "Screen Solver (Floating)";
            pip.document.body.style.margin = "0";
            pip.document.body.style.padding = "0";
            pip.document.body.style.background = "#050507";
            pip.document.body.style.overflow = "hidden";

            // Move solverOverlay into PiP window
            pip.document.body.appendChild(solverOverlay);
            solverOverlay.style.position = "static";
            solverOverlay.style.width = "100%";
            solverOverlay.style.height = "100%";
            solverOverlay.style.maxWidth = "100%";
            solverOverlay.style.maxHeight = "100%";
            solverOverlay.style.boxShadow = "none";
            solverOverlay.style.borderRadius = "0";
            solverOverlay.style.border = "none";
            solverOverlay.style.display = "flex";

            if (solverBtnPip) solverBtnPip.style.display = "none";

            pip.addEventListener("pagehide", function() {
                var vp = document.querySelector(".viewport") || document.body;
                vp.appendChild(solverOverlay);
                solverOverlay.style.position = "fixed";
                solverOverlay.style.width = "440px";
                solverOverlay.style.height = "auto";
                solverOverlay.style.maxWidth = "calc(100vw - 32px)";
                solverOverlay.style.maxHeight = "calc(100vh - 70px)";
                solverOverlay.style.boxShadow = "0 24px 60px rgba(0, 0, 0, 0.88)";
                solverOverlay.style.borderRadius = "14px";
                solverOverlay.style.border = "1px solid rgba(255, 255, 255, 0.12)";
                if (solverBtnPip) solverBtnPip.style.display = "inline-flex";
                activePipWindow = null;
            });
            return true;
        } catch (err) {
            console.warn("Could not open Document PiP:", err);
            return false;
        }
    }
    window.popOutToPip = popOutToPip;

    function copyBookmarkletCode() {
