    async function startScreenShare() {
        try {
            if (!navigator.mediaDevices || !navigator.mediaDevices.getDisplayMedia) {
                alert("Screenshare is not supported on this browser or context.");
                return false;
            }

            var captureCtrl = null;
            if ("CaptureController" in window) {
                try {
                    captureCtrl = new CaptureController();
                    if ("setFocusBehavior" in captureCtrl) {
                        captureCtrl.setFocusBehavior("focus-captured-surface");
                    }
                } catch (e) {}
            }

            var opts = {
                video: {
                    cursor: "always",
                    displaySurface: "browser"
                },
                audio: false
            };
            if (captureCtrl) {
                opts.controller = captureCtrl;
            }

            var stream = await navigator.mediaDevices.getDisplayMedia(opts);
            solverStream = stream;
            solverVideo.srcObject = stream;
            solverVideo.play();
            solverNoStream.style.display = "none";
            solverVideo.style.display = "block";

            var track = stream.getVideoTracks()[0];
            track.onended = function() {
                stopScreenShare();
            };

            // Automatically float over target tab (ChatGPT, i-Ready) via Document PiP!
            if ("documentPictureInPicture" in window && (!activePipWindow || activePipWindow.closed)) {
                popOutToPip();
            }

            return true;
        } catch (err) {
            console.warn("Screenshare cancelled or error:", err);
            return false;
        }
    }

    function stopScreenShare() {
        if (solverStream) {
            try {
                solverStream.getTracks().forEach(function(t) { t.stop(); });
            } catch (e) {}
            solverStream = null;
        }
        solverVideo.srcObject = null;
        solverVideo.style.display = "none";
        solverNoStream.style.display = "flex";
    }

    function toggleScreenSolver() {
        if (!solverOverlay) return;
        if (activePipWindow && !activePipWindow.closed) {
            activePipWindow.close();
            return;
        }
        if (solverOverlay.style.display === "flex") {
            solverOverlay.style.display = "none";
        } else {
            solverOverlay.style.display = "flex";
            if (!solverStream) {
                startScreenShare();
            }
        }
    }
    window.toggleScreenSolver = toggleScreenSolver;
    window.solveScreenQuestion = solveScreenQuestion;
    window.solveImageDirect = solveImageDirect;
    if (btnSolverToggle) btnSolverToggle.addEventListener("click", toggleScreenSolver);
    if (aiHeaderSolverBtn) aiHeaderSolverBtn.addEventListener("click", function() {
        if (aiModal) aiModal.style.display = "none";
        toggleScreenSolver();
    });
    if (solverBtnClose) solverBtnClose.addEventListener("click", function() {
        if (activePipWindow && !activePipWindow.closed) {
            activePipWindow.close();
        } else {
            solverOverlay.style.display = "none";
        }
    });
    if (solverBtnX) solverBtnX.addEventListener("click", function() {
        if (activePipWindow && !activePipWindow.closed) {
            activePipWindow.close();
        } else {
            solverOverlay.style.display = "none";
        }
    });
    if (solverBtnSwitch) solverBtnSwitch.addEventListener("click", startScreenShare);
    if (solverBtnStart) solverBtnStart.addEventListener("click", startScreenShare);
    if (solverBtnPip) solverBtnPip.addEventListener("click", popOutToPip);
    if (solverBtnFloat) solverBtnFloat.addEventListener("click", popOutToPip);
    if (solverBtnBookmarklet) solverBtnBookmarklet.addEventListener("click", copyBookmarkletCode);

    // Draggable Solver Window Handle
    if (solverBar && solverOverlay) {
        var isDragging = false, startX, startY, origX, origY;
        solverBar.style.cursor = "grab";
        solverBar.addEventListener("pointerdown", function(e) {
            if (e.target.tagName === "BUTTON" || e.target.closest("button")) return;
            isDragging = true;
            solverBar.style.cursor = "grabbing";
            startX = e.clientX;
            startY = e.clientY;
            var rect = solverOverlay.getBoundingClientRect();
            origX = rect.left;
            origY = rect.top;
            solverOverlay.style.left = origX + "px";
            solverOverlay.style.top = origY + "px";
            solverOverlay.style.right = "auto";
            solverOverlay.style.bottom = "auto";
            try { solverBar.setPointerCapture(e.pointerId); } catch(err){}
        });
        solverBar.addEventListener("pointermove", function(e) {
            if (!isDragging) return;
            var dx = e.clientX - startX;
            var dy = e.clientY - startY;
            var newL = Math.max(8, Math.min(window.innerWidth - solverOverlay.offsetWidth - 8, origX + dx));
            var newT = Math.max(8, Math.min(window.innerHeight - solverOverlay.offsetHeight - 8, origY + dy));
            solverOverlay.style.left = newL + "px";
            solverOverlay.style.top = newT + "px";
        });
        var endDrag = function(e) {
            if (!isDragging) return;
            isDragging = false;
            solverBar.style.cursor = "grab";
            try { solverBar.releasePointerCapture(e.pointerId); } catch(err){}
        };
        solverBar.addEventListener("pointerup", endDrag);
        solverBar.addEventListener("pointercancel", endDrag);
    }

    // Solve Screen Question
    async function solveScreenQuestion() {
        if (!solverStream) {
            var ok = await startScreenShare();
            if (!ok) return;
            await new Promise(function(r) { setTimeout(r, 600); });
        }

        var vw = solverVideo.videoWidth || 1920;
        var vh = solverVideo.videoHeight || 1080;
        if (vw < 10 || vh < 10) {
            alert("Video frame not ready. Please wait a second and press Solve question again.");
            return;
        }

        // Downscale to max dimension 850px for ultra-fast 20ms transfer (<50KB) and razor-sharp clarity
        var maxDim = 850;
        var scale = Math.min(1, maxDim / Math.max(vw, vh));
        var targetW = Math.max(100, Math.round(vw * scale));
        var targetH = Math.max(100, Math.round(vh * scale));

        var cv = document.createElement("canvas");
        cv.width = targetW;
        cv.height = targetH;
        var ctx = cv.getContext("2d");
        ctx.imageSmoothingEnabled = true;
        ctx.imageSmoothingQuality = "high";
        ctx.drawImage(solverVideo, 0, 0, targetW, targetH);
        var frameDataUrl = cv.toDataURL("image/jpeg", 0.78);

        var customQ = (solverInput.value || "").trim();
        await solveImageDirect(frameDataUrl, customQ);
    }
    window.solveScreenQuestion = solveScreenQuestion;

    async function solveImageDirect(dataUrl, promptText) {
        window.solveImageDirect = solveImageDirect;
        solverBtnSolve.disabled = true;
        solverBtnSolve.textContent = "⚡ Analyzing...";
        solverResultPanel.style.display = "flex";
        solverAnswerBox.innerHTML = '<div style="color:#d2b8ff">⚡ Scanning pixels &amp; calculating exact answer...</div>';
        solverStatusBadge.textContent = "⚡ Solving...";

        var t0 = performance.now();
        var sysPrompt = 
            "You are an elite academic test solver for i-Ready, school exams, standardized tests, and math/reading quizzes.\n" +
            "Analyze the image with meticulous precision. Read every word, diagram, number, and question choice.\n" +
            "FORMAT:\n" +
            "1. Output the final correct answer in bold at the very top: '**ANSWER: [Option Letter or Value]**' (e.g. '**ANSWER: B**' or '**ANSWER: 42**').\n" +
            "2. Below it, provide a concise 1-2 sentence proof/verification.\n" +
            "3. Be 100% accurate and mathematically verified.";

        var userContent = [
            { type: "text", text: promptText ? ("User instruction: " + promptText + "\nSolve the question accurately.") : "Solve the question shown on screen with 100% precision." },
            { type: "image_url", image_url: { url: dataUrl } }
        ];

        var fullSolution = "";
        for (var i = 0; i < VISION_MODELS.length; i++) {
            var model = VISION_MODELS[i];
            try {
                var resp = await fetch("https://openrouter.ai/api/v1/chat/completions", {
                    method: "POST",
                    headers: {
                        "Authorization": "Bearer " + AI_KEY,
                        "Content-Type": "application/json",
                        "HTTP-Referer": location.origin || "http://localhost",
                        "X-Title": "younis"
                    },
                    body: JSON.stringify({
                        model: model,
                        messages: [
                            { role: "system", content: sysPrompt },
                            { role: "user", content: userContent }
                        ],
                        stream: true
                    })
                });

                if (!resp.ok || !resp.body) continue;

                var reader = resp.body.getReader();
                var decoder = new TextDecoder();
                var buf = "";
                solverAnswerBox.innerHTML = "";

                while (true) {
                    var chunk = await reader.read();
                    if (chunk.done) break;
                    buf += decoder.decode(chunk.value, { stream: true });
                    var lines = buf.split(/\r?\n/);
                    buf = lines.pop() || "";
                    for (var li = 0; li < lines.length; li++) {
                        var l = lines[li].trim();
                        if (!l.startsWith("data:")) continue;
                        var dStr = l.slice(5).trim();
                        if (dStr === "[DONE]") break;
                        try {
                            var p = JSON.parse(dStr);
                            var delta = p.choices && p.choices[0] && p.choices[0].delta;
                            var c = (delta && delta.content) || (p.choices && p.choices[0] && p.choices[0].message && p.choices[0].message.content);
                            if (c) {
                                fullSolution += c;
                                renderFormattedSolution(fullSolution);
                            }
                        } catch (err) {}
                    }
                }

                if (fullSolution) {
                    var dt = ((performance.now() - t0) / 1000).toFixed(1);
                    solverStatusBadge.textContent = "⚡ Solved in " + dt + "s";
                    solverBtnSolve.disabled = false;
                    solverBtnSolve.textContent = "Solve question";
                    return;
                }
            } catch (err) {
                console.warn("Vision solver error on", model, err);
            }
        }

        solverStatusBadge.textContent = "⚠️ Error";
        solverAnswerBox.innerHTML = '<div style="color:#ff6b6b">Could not solve question. Please verify connection and try again.</div>';
        solverBtnSolve.disabled = false;
        solverBtnSolve.textContent = "Solve question";
    }

    function renderFormattedSolution(text) {
        var clean = text.trim();
        var match = clean.match(/\*\*ANSWER:\s*([^\*]+)\*\*/i) || clean.match(/^ANSWER:\s*([^\n]+)/i);
        if (match) {
            var ans = match[1].trim();
            var rest = clean.replace(match[0], "").trim();
            solverAnswerBox.innerHTML = 
                '<div class="solver-highlight-ans">&#x2714; Correct Answer: ' + escapeHtml(ans) + '</div>' +
                '<div style="margin-top:6px;line-height:1.45">' + escapeHtml(rest) + '</div>';
        } else {
            solverAnswerBox.textContent = clean;
        }
    }

    function escapeHtml(str) {
        return String(str).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
    }

    if (solverBtnSolve) solverBtnSolve.addEventListener("click", solveScreenQuestion);

    if (solverBtnCopy) {
        solverBtnCopy.addEventListener("click", function() {
            var txt = solverAnswerBox.innerText || solverAnswerBox.textContent;
            if (txt && navigator.clipboard) {
                navigator.clipboard.writeText(txt);
                var orig = solverBtnCopy.textContent;
                solverBtnCopy.textContent = "Copied!";
                setTimeout(function() { solverBtnCopy.textContent = orig; }, 1500);
            }
        });
    }

})();
